(* [comment removed for export] *)
Lemma cookie_fold : forall m C cs,
  rw_cells asegs m C cs -> cells_size cs = 15%nat -> firstn 8 (cells_bytes cs) = zeros 8 ->
  rw_cells asegs m C (CookieCells (skipn 8 (cells_bytes cs))).
Proof.
  intros m C cs RC SZ F8. pose proof RC as [[WF _] _]. pose proof (cells_bytes_length cs WF) as L. rewrite SZ in L.
  eapply rw_cells_reshape; [exact RC| |].
  - cbn. rewrite length_skipn. repeat split; lia.
  - unfold CookieCells. cbn [cells_bytes cbytes app]. rewrite app_nil_r, <- F8. apply firstn_skipn.
Qed.

Lemma rw_cells_nil : forall m A, 0 <= A <= 2^64 -> rw_cells asegs m A [].
Proof.
  intros m A HA. split; [split; [exact I|]|].
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
  - split; [lia|]. split; [cbn; lia|]. intros i Hi. cbn in Hi. lia.
Qed.

