  Lemma chain_munch_stack : forall m m' cur CH l h,
    as_chain H m cur CH -> munch [(l, h)]%Z m m' -> (forall fp ra, In (fp, ra) CH -> h + 16 <= fp) -> 0 <= l ->
    as_chain H m' cur CH.
  Proof.
    intros m m' cur CH l h CHN MU ABOVE L0. eapply (ah_chain_ext H HH); [exact CHN|].
    intros fp ra a IN Ha. pose proof (ah_chain_range H HH _ _ _ _ _ CHN IN) as (R1 & R2 & R3). pose proof (ABOVE _ _ IN) as AB.
    pose proof aceil_facts as (AF1 & _).
    apply MU. unfold wa. rewrite unsigned_lit by lia. cbn. split; [lia| exact I].
  Qed.

  (* [comment removed for export] *)
  Lemma AAllocImpl_after_free : forall s LB m bp p n SP m1 m2 allocb,
    as_RHEAP H s LB m -> In (bp, p, n) LB -> n <> SZ_ALLOCIMPL ->
    AAllocImpl LB m1 allocb -> apres H (as_lb_remove H bp LB) SP m1 m2 ->
    AAllocImpl (as_lb_remove H bp LB) m2 allocb.
  Proof.
    intros s LB m bp p n SP m1 m2 allocb HP IN NE (pa & junk & INa & C & RB & AD) AP.
    pose proof (ah_nodup H HH _ _ _ HP) as ND.
    assert (INa' : In (pa, allocb, SZ_ALLOCIMPL) (as_lb_remove H bp LB)).
    { apply (ah_lb_remove_keep H HH); [exact ND| exact INa|]. cbn. intros E.
      assert (EQ : (pa, allocb, SZ_ALLOCIMPL) = (bp, p, n)) by (eapply nodup_blk_eq; [exact ND| exact INa| exact IN| exact E]).
      inversion EQ. congruence. }
    exists pa, junk. split; [exact INa'|]. split.
    - eapply (apres_rw_cells H); [exact AP| exact C|]. right; right; left. exists (pa, allocb, SZ_ALLOCIMPL).
      split; [exact INa'|]. cbn [blk_addr blk_size fst snd cells_size csize Nat.add]. unfold SZ_ALLOCIMPL. lia.
    - split; [exact RB|]. eapply (apres_addressable H); [exact AP| exact AD| exact INa'].
  Qed.


  (* [comment removed for export] *)
  Lemma seg_stack_bundle : forall s LB LF B m m1 l h lo shi,
    as_RHEAP H s LB m -> as_RFS H LF m -> ACONST m -> as_rauxv_ok H m B -> stack0 m lo shi ->
    munch [(l, h)]%Z m m1 -> wmono asegs m m1 -> aceil <= l ->
    as_RHEAP H s LB m1 /\ as_RFS H LF m1 /\ ACONST m1 /\ as_rauxv_ok H m1 B /\ stack0 m1 lo shi.
  Proof.
    intros s LB LF B m m1 l h lo shi HP RF AC AUX SK MU WM CE. pose proof aceil_facts as (AF1 & _).
    destruct (stack_window_ok' H HH s LB m LF l h HP CE) as (W1 & W2 & W3).
    destruct (client_frame H HH s LB LF B _ m m1 HP RF AC AUX MU WM
                ltac:(constructor; [exact W1| constructor]) ltac:(constructor; [exact W2| constructor]) ltac:(constructor; [exact W3| constructor]))
      as (HP1 & RF1 & AC1 & AUX1).
    split; [exact HP1|]. split; [exact RF1|]. split; [exact AC1|]. split; [exact AUX1|].
    eapply stack0_transport; [exact SK| exact MU| exact WM|]. constructor; [apply stack0_ok_app; unfold AHI_LO; lia| constructor].
  Qed.
